#!/vendor/bin/sh
bus=3
function init()
{
    insmod /vendor_dlkm/lib/modules/i2c-dev.ko
    insmod /vendor_dlkm/lib/modules/i2c-gpio.ko
    /vendor/bin/i2ctransfer  -f -y $bus w4@0x11 0x40 0x08 0x50 0x58 w4@0x11 0xCA 0xFE 0x02 0xF7
    /vendor/bin/i2ctransfer  -f -y $bus w4@0x11 0xCA 0xFE 0x02 0xF3 w4@0x11 0xCA 0xFE 0x02 0xF1
    /vendor/bin/i2ctransfer  -f -y $bus w4@0x11 0x40 0x08 0x50 0x58 w4@0x11 0xCA 0xFE 0x02 0xF0
    /vendor/bin/i2ctransfer  -f -y $bus w4@0x11 0x40 0x08 0x00 0xA0 w4@0x11 0x00 0x00 0x10 0x00
    /vendor/bin/i2ctransfer  -f -y $bus w4@0x11 0x40 0x08 0x00 0xCC w4@0x11 0x00 0x00 0x00 0x04
}

function dump_reg()
{
    echo "pc:"
    /vendor/bin/i2ctransfer  -f -y $bus w4@0x11 0x50 0x00 0x00 0x54 w4@0x11 0x00 0x00 0x01 0x03
    /vendor/bin/i2ctransfer  -f -y $bus w4@0x11 0x50 0x00 0x00 0xf4 r4

    echo "lr:"
    /vendor/bin/i2ctransfer  -f -y $bus w4@0x11 0x50 0x00 0x00 0x54 w4@0x11 0x00 0x00 0x09 0x03
    /vendor/bin/i2ctransfer  -f -y $bus w4@0x11 0x50 0x00 0x00 0xf4 r4

    echo "sp:"
    /vendor/bin/i2ctransfer  -f -y $bus w4@0x11 0x50 0x00 0x00 0x54 w4@0x11 0x00 0x00 0x11 0x03
    /vendor/bin/i2ctransfer  -f -y $bus w4@0x11 0x50 0x00 0x00 0xf4 r4
}

function switch_jtag()
{
    echo "switch to jtag"
    /vendor/bin/i2ctransfer  -f -y $bus w4@0x11 0x40 0x08 0x00 0x04 w4@0x11 0x00 0x00 0x00 0x08
    /vendor/bin/i2ctransfer  -f -y $bus w4@0x11 0x40 0x08 0x60 0x0C w4@0x11 0xFF 0xFF 0x22 0xFF
    /vendor/bin/i2ctransfer  -f -y $bus w4@0x11 0x40 0x08 0x60 0x48 w4@0x11 0x00 0x00 0x00 0x03
}

function deinit()
{
    rmmod i2c_gpio
    rmmod i2c_dev
}

init
switch_jtag
deinit
